-- =====================================================================
-- Catálogo de misconceptions — unidad GEO-TRA
-- Generado por cargar_misconceptions.py desde GEO-TRA.yaml
-- NO EDITAR A MANO. Se edita el YAML y se vuelve a generar.
-- La transaccion la pone quien ejecuta:
--   psql -X -v ON_ERROR_STOP=1 -1 -f este_archivo.sql "$DATABASE_URL"
-- Este archivo NO trae begin/commit a proposito: anidarlos rompe
-- la atomicidad del -1.
-- =====================================================================

insert into misconceptions (code, name, description, example, area_id, node_id, origin)
select v.code, v.name, v.description, v.example, a.id, n.id,
       v.origin::misconception_origin
from (values
  ($c$PLA-COORD-ORDEN$c$, $c$Invierte el orden de las coordenadas$c$, $c$Escribe o lee (y, x) en vez de (x, y): el punto 4 a la derecha y 3 abajo lo anota (−3, 4), y ubica (2, 7) a 7 unidades del eje y. Es la misconception central del nodo. Confunde también abscisa con ordenada.$c$, $c$4 a la derecha y 3 abajo → (−3, 4)$c$, $c$GEO$c$, $c$GEO-PLA-COORD$c$, $c$hipotesis$c$),
  ($c$PLA-COORD-SINSIGNO$c$, $c$Lee las coordenadas como distancias, sin signo$c$, $c$Cuenta cuánto se aleja el punto de cada eje y no mira hacia dónde: todo punto le queda con coordenadas positivas. Entre dos puntos alineados resta los tamaños (de −3 a 4 hay 1).$c$, $c$punto 4 a la izquierda y 3 arriba → (4, 3)$c$, $c$GEO$c$, $c$GEO-PLA-COORD$c$, $c$hipotesis$c$),
  ($c$PLA-COORD-CUADNUM$c$, $c$Numera los cuadrantes en el sentido equivocado$c$, $c$Numera los cuadrantes en sentido horario (como un reloj) a partir del primero: el de abajo a la derecha queda como "segundo" y el de arriba a la izquierda como "cuarto". Acierta en el primero y el tercero; falla solo en el segundo y el cuarto.$c$, $c$(5, −1) está en el segundo cuadrante$c$, $c$GEO$c$, $c$GEO-PLA-COORD$c$, $c$hipotesis$c$),
  ($c$PLA-COORD-EJECERO$c$, $c$Cree que (0, a) está sobre el eje x$c$, $c$Asocia el 0 de la primera coordenada con el eje x ("la x es 0, está en el eje x"), y al revés: (a, 0) le parece sobre el eje y. Todo punto con x = 0 está sobre el eje y.$c$, $c$(0, −4) está sobre el eje x$c$, $c$GEO$c$, $c$GEO-PLA-COORD$c$, $c$hipotesis$c$),
  ($c$PLA-COORD-EJECUAD$c$, $c$Ubica en un cuadrante un punto que está sobre un eje$c$, $c$No sabe que los puntos de los ejes no pertenecen a ningún cuadrante: (0, 2) le parece del primero y (−6, 0) del tercero, por el signo de la coordenada que no es cero.$c$, $c$(0, 2) está en el primer cuadrante$c$, $c$GEO$c$, $c$GEO-PLA-COORD$c$, $c$hipotesis$c$),
  ($c$PLA-COORD-ESCALA$c$, $c$Cuenta cuadrados como si cada uno valiera 1$c$, $c$En una cuadrícula cuyos ejes van de 2 en 2 (o de 5 en 5), lee las coordenadas contando cuadrados: un punto en (−6, 4) le queda en (−3, 2). Es la versión en el plano de ENT-REC-ESCALA. Solo aparece con figura.$c$, $c$escala 2: (−6, 4) leído como (−3, 2)$c$, $c$GEO$c$, $c$GEO-PLA-COORD$c$, $c$hipotesis$c$),
  ($c$PLA-COORD-CONTEO$c$, $c$Cuenta líneas de la cuadrícula en vez de espacios$c$, $c$Cuenta las líneas (o los puntos de la cuadrícula) incluyendo la de partida: entre x = −3 y x = 4 cuenta 8, y al leer un punto cuenta el eje como la primera línea (un punto en (4, −3) le queda en (5, −4)). Es la versión en el plano de ENT-REC-CONTEO.$c$, $c$de (−3, 2) a (4, 2) hay 8 unidades$c$, $c$GEO$c$, $c$GEO-PLA-COORD$c$, $c$hipotesis$c$),
  ($c$PLA-VEC-ORIGEN$c$, $c$Calcula el vector como inicio menos final$c$, $c$Resta al revés: el vector de A a B lo calcula como A − B, y le queda el opuesto. Con una figura, cuenta desde la punta hacia la cola. Es la misconception central del nodo.$c$, $c$A(2, −1), B(5, 3): AB = (−3, −4)$c$, $c$GEO$c$, $c$GEO-PLA-VEC$c$, $c$hipotesis$c$),
  ($c$PLA-VEC-PUNTO$c$, $c$Toma las coordenadas del extremo como componentes$c$, $c$Cree que las componentes de un vector son las coordenadas del punto donde termina, sin restar el origen. Acierta solo cuando el vector parte del (0, 0), y por eso se sostiene.$c$, $c$de (2, −1) a (5, 3): componentes (5, 3)$c$, $c$GEO$c$, $c$GEO-PLA-VEC$c$, $c$hipotesis$c$),
  ($c$PLA-VEC-SUMA$c$, $c$Suma las coordenadas de los dos puntos$c$, $c$Calcula el vector de A a B como A + B. Sabe que hay que operar las coordenadas de los dos puntos, pero no cuál operación.$c$, $c$A(2, −1), B(5, 3): AB = (7, 2)$c$, $c$GEO$c$, $c$GEO-PLA-VEC$c$, $c$hipotesis$c$),
  ($c$PLA-VEC-POSICION$c$, $c$Cree que un vector depende de dónde parte$c$, $c$Piensa que dos flechas con la misma dirección, sentido y largo son vectores distintos si parten de puntos distintos. El vector es el desplazamiento, no la flecha dibujada en un lugar.$c$, $c$de (0, 0) a (2, 1) y de (3, 3) a (5, 4) son vectores distintos$c$, $c$GEO$c$, $c$GEO-PLA-VEC$c$, $c$hipotesis$c$),
  ($c$PLA-VEC-SINSIGNO$c$, $c$Cuenta las componentes sin mirar el sentido$c$, $c$Cuenta cuántos cuadrados avanza la flecha en cada dirección, pero no hacia dónde: todas las componentes le quedan positivas, y un vector y su opuesto le parecen iguales.$c$, $c$flecha 5 a la derecha y 2 abajo: (5, 2)$c$, $c$GEO$c$, $c$GEO-PLA-VEC$c$, $c$hipotesis$c$),
  ($c$PLA-VECOP-RESTAORDEN$c$, $c$Resta los vectores al revés$c$, $c$Calcula u − v como v − u, o al despejar un vector que falta resta en el orden equivocado. El resultado es el opuesto del correcto.$c$, $c$(5, 1) − (2, 3) = (−3, 2)$c$, $c$GEO$c$, $c$GEO-PLA-VEC-OP$c$, $c$hipotesis$c$),
  ($c$PLA-VECOP-SINSENTIDO$c$, $c$Suma los desplazamientos sin mirar su sentido$c$, $c$Junta dos movimientos sumando lo que mide cada uno, aunque vayan en sentidos contrarios: 5 al este y 8 al oeste le dan 13. Es la misconception central del nodo en contexto.$c$, $c$5 al este y 8 al oeste: (13, 0)$c$, $c$GEO$c$, $c$GEO-PLA-VEC-OP$c$, $c$hipotesis$c$),
  ($c$PLA-VECOP-PUNTAS$c$, $c$Toma la otra diagonal como vector suma$c$, $c$Con dos vectores dibujados desde un mismo punto, da como suma el segmento que une sus puntas (que es la diferencia) en vez de la diagonal que parte del origen común. Al revés, cuando piden la diferencia da la suma.$c$, $c$u = (3, −1), v = (−1, 3): u + v = (−4, 4)$c$, $c$GEO$c$, $c$GEO-PLA-VEC-OP$c$, $c$hipotesis$c$),
  ($c$TRA-TRAS-SENTIDO$c$, $c$Aplica el vector de traslación en sentido contrario$c$, $c$Al trasladar resta el vector (P − v), y al buscar el punto de origen a partir de la imagen vuelve a sumarlo. Confunde "trasladar según v" con "deshacer v". Es la misconception central del nodo.$c$, $c$P(2, −3) según (−4, 5) → (6, −8)$c$, $c$GEO$c$, $c$GEO-TRA-TRAS$c$, $c$hipotesis$c$),
  ($c$TRA-TRAS-FORMA$c$, $c$Cree que una traslación puede girar o deformar la figura$c$, $c$No sabe que la traslación solo desplaza: acepta como traslación una imagen girada o reflejada, o cree que los lados pueden cambiar de largo o de dirección. Solo aparece en ítems de figura o de propiedades.$c$, $c$la imagen trasladada de un triángulo puede quedar girada$c$, $c$GEO$c$, $c$GEO-TRA-TRAS$c$, $c$hipotesis$c$),
  ($c$TRA-REFEJE-CAMBIAEJE$c$, $c$Cambia la coordenada equivocada al reflejar en un eje$c$, $c$Al reflejar respecto del eje x cambia el signo de la x (y respecto del eje y, el de la y). Asocia "eje x" con "la x cambia", cuando el eje x es justamente la coordenada que se conserva. Es la misconception central del nodo.$c$, $c$(3, −5) respecto del eje x → (−3, −5)$c$, $c$GEO$c$, $c$GEO-TRA-REF-EJE$c$, $c$hipotesis$c$),
  ($c$TRA-REFEJE-AMBOS$c$, $c$Cambia el signo de las dos coordenadas$c$, $c$Cree que reflejar es "cambiar los signos" y cambia los dos: hace una simetría respecto del origen en vez de una reflexión en un eje.$c$, $c$(3, −5) respecto del eje x → (−3, 5)$c$, $c$GEO$c$, $c$GEO-TRA-REF-EJE$c$, $c$hipotesis$c$),
  ($c$TRA-REFEJE-INTERCAMBIA$c$, $c$Intercambia las coordenadas al reflejar$c$, $c$Refleja cambiando el orden de las coordenadas, (x, y) → (y, x), a veces con un signo. Es la regla de la recta y = x aplicada a los ejes.$c$, $c$(3, −5) respecto del eje x → (−5, 3)$c$, $c$GEO$c$, $c$GEO-TRA-REF-EJE$c$, $c$hipotesis$c$),
  ($c$TRA-REFEJE-TRASLADA$c$, $c$Pasa la figura al otro lado sin darla vuelta$c$, $c$Lleva la figura al otro lado del eje conservando su orientación, como si fuera una traslación. No ve que la reflexión invierte la figura: lo que estaba cerca del eje sigue cerca del eje. Solo aparece con figuras.$c$, $c$triángulo reflejado en el eje y que conserva hacia dónde apunta$c$, $c$GEO$c$, $c$GEO-TRA-REF-EJE$c$, $c$hipotesis$c$),
  ($c$TRA-REFEJE-PROYECTA$c$, $c$Deja el punto sobre el eje$c$, $c$Mueve el punto hasta el eje y se detiene: (5, −3) reflejado en el eje x queda en (5, 0). Recorre la mitad del camino. Hipótesis débil, se mantiene para ver si aparece.$c$, $c$(5, −3) respecto del eje x → (5, 0)$c$, $c$GEO$c$, $c$GEO-TRA-REF-EJE$c$, $c$hipotesis$c$),
  ($c$TRA-REFREC-EJE$c$, $c$Refleja respecto del eje en vez de la recta dada$c$, $c$Ignora dónde está la recta y aplica la regla del eje paralelo: (5, 2) respecto de x = 1 le queda (−5, 2). Con y = x o y = −x refleja en el eje más cercano. Es la misconception central del nodo.$c$, $c$(5, 2) respecto de x = 1 → (−5, 2)$c$, $c$GEO$c$, $c$GEO-TRA-REF-REC$c$, $c$hipotesis$c$),
  ($c$TRA-REFREC-RECTAX$c$, $c$Lee la recta x = a como horizontal$c$, $c$Cree que x = a es una recta horizontal (o y = b una vertical), y cambia la coordenada equivocada: respecto de x = 1 refleja la y.$c$, $c$(5, 2) respecto de x = 1 → (5, 0)$c$, $c$GEO$c$, $c$GEO-TRA-REF-REC$c$, $c$hipotesis$c$),
  ($c$TRA-REFREC-RESTA$c$, $c$Calcula la imagen como a − x$c$, $c$Resta la coordenada al valor de la recta, x' = a − x, en vez de x' = 2a − x. Acierta solo con a = 0. Hipótesis: sin evidencia, se mantiene para ver si aparece.$c$, $c$(5, 2) respecto de x = 1 → (−4, 2)$c$, $c$GEO$c$, $c$GEO-TRA-REF-REC$c$, $c$hipotesis$c$),
  ($c$TRA-REFREC-DIAG$c$, $c$Confunde la recta y = x con y = −x$c$, $c$Al reflejar respecto de y = x cambia los signos además de intercambiar, (x, y) → (−y, −x), que es la regla de y = −x; y al revés con y = −x.$c$, $c$(4, −2) respecto de y = x → (2, −4)$c$, $c$GEO$c$, $c$GEO-TRA-REF-REC$c$, $c$hipotesis$c$),
  ($c$TRA-ROT90-SENTIDO$c$, $c$Gira en el sentido contrario$c$, $c$Aplica la regla del giro horario cuando se pide antihorario, o al revés: (3, 1) girado 90° antihorario le queda (1, −3). Es la misconception central del nodo.$c$, $c$(3, 1), 90° antihorario → (1, −3)$c$, $c$GEO$c$, $c$GEO-TRA-ROT-90$c$, $c$hipotesis$c$),
  ($c$TRA-ROT90-SOLOCAMBIA$c$, $c$Intercambia las coordenadas sin cambiar signos$c$, $c$Recuerda que girar 90° "intercambia" las coordenadas, pero no el cambio de signo: (3, 1) → (1, 3). Eso es reflejar en la recta y = x.$c$, $c$(3, 1), 90° antihorario → (1, 3)$c$, $c$GEO$c$, $c$GEO-TRA-ROT-90$c$, $c$hipotesis$c$),
  ($c$TRA-ROT90-SOLOSIGNO$c$, $c$Cambia un signo sin intercambiar$c$, $c$Gira cambiando el signo de una coordenada y dejándolas en su lugar: (3, 1) → (−3, 1). Eso es reflejar en un eje. En 180° cambia un solo signo en vez de los dos.$c$, $c$(3, 1), 90° antihorario → (−3, 1)$c$, $c$GEO$c$, $c$GEO-TRA-ROT-90$c$, $c$hipotesis$c$),
  ($c$TRA-ROT90-ANGULO$c$, $c$Confunde el giro de 90° con el de 180°$c$, $c$Aplica la regla de 180° (cambiar los dos signos) a un giro de 90°, o la de 90° a uno de 180°. En 270° usa la regla de 180° o la de 90°.$c$, $c$(3, 1), 90° antihorario → (−3, −1)$c$, $c$GEO$c$, $c$GEO-TRA-ROT-90$c$, $c$hipotesis$c$),
  ($c$TRA-ROTCEN-ORIGEN$c$, $c$Gira respecto del origen en vez del centro dado$c$, $c$Ignora el centro de rotación y aplica la regla del origen: (4, 1) girado 90° antihorario respecto de (1, 1) le queda (−1, 4). Es la misconception central del nodo.$c$, $c$(4, 1), 90° antihorario respecto de (1, 1) → (−1, 4)$c$, $c$GEO$c$, $c$GEO-TRA-ROT-CEN$c$, $c$hipotesis$c$),
  ($c$TRA-ROTCEN-NOVUELVE$c$, $c$Gira el vector desde el centro y no vuelve a sumar el centro$c$, $c$Hace bien el primer paso (restar el centro) y el giro, pero entrega el vector girado como si fuera el punto: (4, 1) respecto de (1, 1) le queda (0, 3).$c$, $c$(4, 1), 90° antihorario respecto de (1, 1) → (0, 3)$c$, $c$GEO$c$, $c$GEO-TRA-ROT-CEN$c$, $c$hipotesis$c$),
  ($c$TRA-ROTCEN-VUELVEMAL$c$, $c$Al volver, resta el centro otra vez$c$, $c$Resta el centro, gira y vuelve a restar el centro en vez de sumarlo: (4, 1) respecto de (1, 1) → (0, 3) − (1, 1) = (−1, 2).$c$, $c$(4, 1), 90° antihorario respecto de (1, 1) → (−1, 2)$c$, $c$GEO$c$, $c$GEO-TRA-ROT-CEN$c$, $c$hipotesis$c$),
  ($c$TRA-SIMCEN-EJE$c$, $c$Hace una reflexión en un eje en vez de la simetría central$c$, $c$Cambia el signo de una sola coordenada (o, con centro C, refleja solo una coordenada respecto de C): (4, −3) respecto del origen → (4, 3). Confunde simetría central con simetría axial. Es la misconception central del nodo.$c$, $c$(4, −3) respecto del origen → (4, 3)$c$, $c$GEO$c$, $c$GEO-TRA-SIM-CEN$c$, $c$hipotesis$c$),
  ($c$TRA-SIMCEN-ORIGEN$c$, $c$Usa el origen como centro aunque el centro sea otro$c$, $c$Con un centro C distinto del origen, cambia los dos signos igual: (5, 1) respecto de (2, 3) → (−5, −1).$c$, $c$(5, 1) respecto de (2, 3) → (−5, −1)$c$, $c$GEO$c$, $c$GEO-TRA-SIM-CEN$c$, $c$hipotesis$c$),
  ($c$TRA-SIMCEN-RESTA$c$, $c$Calcula el simétrico como C − P$c$, $c$Resta el punto al centro (o el centro al punto) y entrega ese vector como el simétrico: (5, 1) respecto de (2, 3) → (−3, 2). Acierta con el origen como centro, y por eso se sostiene. Al buscar el centro, da la diferencia entre P y P' en vez del punto medio.$c$, $c$(5, 1) respecto de (2, 3) → (−3, 2)$c$, $c$GEO$c$, $c$GEO-TRA-SIM-CEN$c$, $c$hipotesis$c$),
  ($c$TRA-SIMCEN-SINGIRAR$c$, $c$Lleva la figura al lado opuesto sin girarla$c$, $c$Pone la figura en el cuadrante opuesto conservando hacia dónde apunta, como una traslación. La simetría central la gira en 180°: queda "de cabeza". Solo aparece con figuras o en afirmaciones.$c$, $c$triángulo con la punta arriba → imagen con la punta arriba$c$, $c$GEO$c$, $c$GEO-TRA-SIM-CEN$c$, $c$hipotesis$c$)
) as v(code, name, description, example, area_code, node_code, origin)
left join areas a on a.code = v.area_code
join nodes n      on n.code = v.node_code
on conflict (code) do update
  set name        = excluded.name,
      description = excluded.description,
      example     = excluded.example,
      node_id     = excluded.node_id,
      origin      = excluded.origin;

-- Verificación. Si algo no cuadra, revienta y no commitea. ----------
do $verif$
declare c integer;
begin
  select count(*) into c from misconceptions where code in ($c$PLA-COORD-ORDEN$c$, $c$PLA-COORD-SINSIGNO$c$, $c$PLA-COORD-CUADNUM$c$, $c$PLA-COORD-EJECERO$c$, $c$PLA-COORD-EJECUAD$c$, $c$PLA-COORD-ESCALA$c$, $c$PLA-COORD-CONTEO$c$, $c$PLA-VEC-ORIGEN$c$, $c$PLA-VEC-PUNTO$c$, $c$PLA-VEC-SUMA$c$, $c$PLA-VEC-POSICION$c$, $c$PLA-VEC-SINSIGNO$c$, $c$PLA-VECOP-RESTAORDEN$c$, $c$PLA-VECOP-SINSENTIDO$c$, $c$PLA-VECOP-PUNTAS$c$, $c$TRA-TRAS-SENTIDO$c$, $c$TRA-TRAS-FORMA$c$, $c$TRA-REFEJE-CAMBIAEJE$c$, $c$TRA-REFEJE-AMBOS$c$, $c$TRA-REFEJE-INTERCAMBIA$c$, $c$TRA-REFEJE-TRASLADA$c$, $c$TRA-REFEJE-PROYECTA$c$, $c$TRA-REFREC-EJE$c$, $c$TRA-REFREC-RECTAX$c$, $c$TRA-REFREC-RESTA$c$, $c$TRA-REFREC-DIAG$c$, $c$TRA-ROT90-SENTIDO$c$, $c$TRA-ROT90-SOLOCAMBIA$c$, $c$TRA-ROT90-SOLOSIGNO$c$, $c$TRA-ROT90-ANGULO$c$, $c$TRA-ROTCEN-ORIGEN$c$, $c$TRA-ROTCEN-NOVUELVE$c$, $c$TRA-ROTCEN-VUELVEMAL$c$, $c$TRA-SIMCEN-EJE$c$, $c$TRA-SIMCEN-ORIGEN$c$, $c$TRA-SIMCEN-RESTA$c$, $c$TRA-SIMCEN-SINGIRAR$c$);
  if c <> 37 then
    raise exception 'catalogo GEO-TRA: se esperaban 37, hay %', c; end if;

  select count(*) into c from misconceptions
   where code in ($c$PLA-COORD-ORDEN$c$, $c$PLA-COORD-SINSIGNO$c$, $c$PLA-COORD-CUADNUM$c$, $c$PLA-COORD-EJECERO$c$, $c$PLA-COORD-EJECUAD$c$, $c$PLA-COORD-ESCALA$c$, $c$PLA-COORD-CONTEO$c$, $c$PLA-VEC-ORIGEN$c$, $c$PLA-VEC-PUNTO$c$, $c$PLA-VEC-SUMA$c$, $c$PLA-VEC-POSICION$c$, $c$PLA-VEC-SINSIGNO$c$, $c$PLA-VECOP-RESTAORDEN$c$, $c$PLA-VECOP-SINSENTIDO$c$, $c$PLA-VECOP-PUNTAS$c$, $c$TRA-TRAS-SENTIDO$c$, $c$TRA-TRAS-FORMA$c$, $c$TRA-REFEJE-CAMBIAEJE$c$, $c$TRA-REFEJE-AMBOS$c$, $c$TRA-REFEJE-INTERCAMBIA$c$, $c$TRA-REFEJE-TRASLADA$c$, $c$TRA-REFEJE-PROYECTA$c$, $c$TRA-REFREC-EJE$c$, $c$TRA-REFREC-RECTAX$c$, $c$TRA-REFREC-RESTA$c$, $c$TRA-REFREC-DIAG$c$, $c$TRA-ROT90-SENTIDO$c$, $c$TRA-ROT90-SOLOCAMBIA$c$, $c$TRA-ROT90-SOLOSIGNO$c$, $c$TRA-ROT90-ANGULO$c$, $c$TRA-ROTCEN-ORIGEN$c$, $c$TRA-ROTCEN-NOVUELVE$c$, $c$TRA-ROTCEN-VUELVEMAL$c$, $c$TRA-SIMCEN-EJE$c$, $c$TRA-SIMCEN-ORIGEN$c$, $c$TRA-SIMCEN-RESTA$c$, $c$TRA-SIMCEN-SINGIRAR$c$) and node_id is null;
  if c <> 0 then
    raise exception '% errores sin nodo donde se ensenan', c; end if;

  select count(*) into c from misconceptions
   where code in ($c$PLA-COORD-ORDEN$c$, $c$PLA-COORD-SINSIGNO$c$, $c$PLA-COORD-CUADNUM$c$, $c$PLA-COORD-EJECERO$c$, $c$PLA-COORD-EJECUAD$c$, $c$PLA-COORD-ESCALA$c$, $c$PLA-COORD-CONTEO$c$, $c$PLA-VEC-ORIGEN$c$, $c$PLA-VEC-PUNTO$c$, $c$PLA-VEC-SUMA$c$, $c$PLA-VEC-POSICION$c$, $c$PLA-VEC-SINSIGNO$c$, $c$PLA-VECOP-RESTAORDEN$c$, $c$PLA-VECOP-SINSENTIDO$c$, $c$PLA-VECOP-PUNTAS$c$, $c$TRA-TRAS-SENTIDO$c$, $c$TRA-TRAS-FORMA$c$, $c$TRA-REFEJE-CAMBIAEJE$c$, $c$TRA-REFEJE-AMBOS$c$, $c$TRA-REFEJE-INTERCAMBIA$c$, $c$TRA-REFEJE-TRASLADA$c$, $c$TRA-REFEJE-PROYECTA$c$, $c$TRA-REFREC-EJE$c$, $c$TRA-REFREC-RECTAX$c$, $c$TRA-REFREC-RESTA$c$, $c$TRA-REFREC-DIAG$c$, $c$TRA-ROT90-SENTIDO$c$, $c$TRA-ROT90-SOLOCAMBIA$c$, $c$TRA-ROT90-SOLOSIGNO$c$, $c$TRA-ROT90-ANGULO$c$, $c$TRA-ROTCEN-ORIGEN$c$, $c$TRA-ROTCEN-NOVUELVE$c$, $c$TRA-ROTCEN-VUELVEMAL$c$, $c$TRA-SIMCEN-EJE$c$, $c$TRA-SIMCEN-ORIGEN$c$, $c$TRA-SIMCEN-RESTA$c$, $c$TRA-SIMCEN-SINGIRAR$c$) and (example is null or example = '');
  if c <> 0 then
    raise exception '% errores sin example', c; end if;
end
$verif$;

-- 37 misconceptions en GEO-TRA (37 hipotesis).
